import{_ as p,a0 as a,w as i,s as l,ao as r,I as s,x as n,a1 as o,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"如何在Ubuntu 13.04和13.10上安装iOS 7的图标 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 13.04和13.10上安装iOS 7的图标 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 13.04和13.10上安装iOS 7的图标 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 13.04和13.10上安装iOS 7的图标 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/How to Install the iOS 7 Icons in Ubuntu 13.04 and Ubuntu 13.10","title":"如何在Ubuntu 13.04和13.10上安装iOS 7的图标","tag":"201310","desc":""},"relativePath":"201310/How to Install the iOS 7 Icons in Ubuntu 13.04 and Ubuntu 13.10.md","filePath":"[post].md"}'),d={name:"201310/How to Install the iOS 7 Icons in Ubuntu 13.04 and Ubuntu 13.10.md"};function b(m,t,U,T,_,c){const e=a("Link");return i(),l("div",null,[t[11]||(t[11]=r(`<h1 id="如何在ubuntu-13-04和13-10上安装ios-7的图标" tabindex="-1">如何在Ubuntu 13.04和13.10上安装iOS 7的图标 <a class="header-anchor" href="#如何在ubuntu-13-04和13-10上安装ios-7的图标" aria-label="Permalink to “如何在Ubuntu 13.04和13.10上安装iOS 7的图标”">​</a></h1><p><strong>这个简单的教程将指导你如何在你的Ubuntu 12.04、13.04和13.10上安装苹果iOS 7操作系统的所有图标。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-the-iOS-7-Icons-in-Ubuntu-13-04-and-Ubuntu-13-10-387709-2.jpg" alt=""></p><p>上面是效果图，安装的图标虽然并不多，但是对于外观的改进来讲却是重大提高。如果Canonical没有在每一个发行版中使用差异甚小的同类图标，那你就不太容易分辨出Ubuntu。</p><p>以前在Ubuntu安装主题、图标甚至是鼠标光标，那叫一个麻烦，但是近几年这事变得容易多了。想要安装新的图标，只需要输入几条命令就行。</p><p>在开始之前，请注意一下。本文使用的PPA(Personal Package Archives)只能在Ubuntu 12.04上运行。这是因为，在复制iOS的图标时候是在Ubuntu 12.04版本上建立的。</p><p>当然，正如开始提到的，这些图标可以在Ubuntu 13.04 和 Ubuntu 13.10上使用，只是需要改变一点小小的操作。</p><p>除此之外，你需要一个小软件使这些图标生效。我们推荐使用GNOME Tweak Tool，但是如果你喜欢的话还有几个其他软件可供选择。</p><p>下面教程开始：</p><p>打开终端，安装GNOME Tweak Tool：</p><pre><code>sudo apt-get install gnome-tweak-tool
</code></pre><p>你会发现这个软件在Ubuntu下叫做Tweak Tool。</p><p>安装PPA，然后更新一下：</p><pre><code>sudo add-apt-repository ppa:elementary-br/projects
sudo apt-get update
</code></pre><p>Ubuntu 12.04安装iOS图标：</p><pre><code>sudo apt-get install ieos7-icons
</code></pre><p>Ubuntu 13.04、Ubuntu 13.10安iOS装图标：</p><pre><code>wget -c https://launchpad.net/~elementary-br/+archive/projects/+files/ieos7-icons_0.1-0~13~ubuntu12.04.1_all.deb
sudo dpkg -i ieos7-icons_0.1-0~13~ubuntu12.04.1_all.deb
</code></pre><p>如果你发现deb包安装失败，无论什么原因，只需要运行：</p><pre><code>sudo apt-get install -f
</code></pre><p>修复完依赖关系，再次运行：</p><pre><code>sudo dpkg -i ieos7-icons_0.1-0~13~ubuntu12.04.1_all.deb
</code></pre><p>这个图标集大概有300个，所以你的操作系统中的部分应用程序图标还是老样子。</p><p>享受你的新图标吧！</p><hr>`,25)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://news.softpedia.com/news/How-to-Install-the-iOS-7-Icons-in-Ubuntu-13-04-and-Ubuntu-13-10-387709.shtml"},{default:u(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/How-to-Install-the-iOS-7-Icons-in-Ubuntu-13-04-and-Ubuntu-13-10-387709.shtml",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:u(()=>[...t[3]||(t[3]=[n("Linux中国",-1)])]),_:1}),t[6]||(t[6]=n(" 荣誉推出",-1))]),s("p",null,[t[9]||(t[9]=n("译者：",-1)),o(e,{href:"https://github.com/vic020"},{default:u(()=>[...t[7]||(t[7]=[n("Vic___",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),o(e,{href:"https://github.com/carolinewuyan"},{default:u(()=>[...t[8]||(t[8]=[n("carolinewuyan",-1)])]),_:1})])])}const w=p(d,[["render",b]]);export{g as __pageData,w as default};
